import {weatherScene} from './weather-scene.js';
import {professionGuide} from './profession.js';
import {forecastReceipt} from './forecast-receipt.js';
import {CITIES} from './places.js';
import {esc,weatherName,miniWeather,valueText,currentHour,bestWindow,trendSummary} from './weather-tools.js';
const $=s=>document.querySelector(s);
export function createAtlas(ctx){
let cities=CITIES,cityLoaded=0,cityLoading=false,cityError='',weatherTab='oggi',activity='walk',compare='milano';
 function contextButton(question,label='Chiedi all’IA'){return `<button class="ai-context" data-atlas-ai="${esc(question)}">✦ ${label}</button>`}
 function weatherHero(){const {place,weather}=ctx.get(),w=weather?.current;return `<section class="weather-hero has-weather-scene">${weatherScene(weather)}<div class="weather-hero-copy"><span class="weather-date">${esc(place.name)} · ${w?esc(w.time.replace('T',' ')):''}</span><div class="weather-big-temp">${valueText(w?.temperature_2m,'°')}</div><h2>${weatherName(w?.weather_code)}</h2><p>Percepiti ${valueText(w?.apparent_temperature,'°')} · Min ${valueText(weather?.daily?.temperature_2m_min?.[0],'°')} · Max ${valueText(weather?.daily?.temperature_2m_max?.[0],'°')}</p><div class="weather-hero-actions">${contextButton('Riassumi il meteo di '+place.name+' in parole semplici, distinguendo previsione e allerte.','Spiegami il meteo')}<button data-atlas-question>Com’è davvero lì?</button></div></div><div class="weather-art" id="weather-art" aria-label="${weatherName(w?.weather_code)}">${miniWeather(w?.weather_code,w?.is_day!==0)}</div>${forecastReceipt(weather)}</section>`}
 function hourCards(){const {weather}=ctx.get(),h=weather?.hourly,start=currentHour(weather);if(start<0)return '<p>Previsione oraria non disponibile.</p>';return `<div class="forecast-hours" tabindex="0" role="region" aria-label="Previsioni orarie scorrevoli">${h.time.slice(start,start+24).map((t,k)=>{const i=k+start;return `<article><time>${t.slice(11,16)}</time>${miniWeather(h.weather_code?.[i],h.is_day?.[i]!==0)}<b>${valueText(h.temperature_2m[i],'°')}</b><span class="rain-prob">${valueText(h.precipitation_probability?.[i],'%')}</span><small>${valueText(h.wind_speed_10m?.[i],' km/h')}</small></article>`}).join('')}</div><p class="forecast-footnote">Percentuali: probabilità di pioggia. Orari della località scelta.</p>`}
 function weatherContent(){const {weather}=ctx.get(),w=weather?.current,d=weather?.daily;if(!weather)return '';if(weatherTab==='ore')return `<section class="forecast-section"><h2>Le prossime 24 ore</h2>${hourCards()}${contextButton('In quali ore aumenta la probabilità di pioggia nelle prossime 24 ore?')}</section>`;
 if(weatherTab==='settimana'){const t=trendSummary(weather);return `<section class="forecast-section"><div class="trend-pills"><div><span>Domani rispetto a oggi</span><strong>${t?.delta==null?'—':(t.delta>0?'+':'')+valueText(t.delta,'°',1)}</strong><small>Variazione della massima prevista</small></div><div><span>Giorno con probabilità più bassa</span><strong>${t?.driest?new Date(d.time[t.driest.i]+'T12:00:00').toLocaleDateString('it-IT',{weekday:'long'}):'—'}</strong><small>${t?.driest?valueText(t.driest.v,'% pioggia'):''}</small></div></div><h2>La settimana, a colpo d’occhio</h2><div class="forecast-week">${(d?.time||[]).map((day,i)=>`<article><b>${i===0?'Oggi':new Date(day+'T12:00:00').toLocaleDateString('it-IT',{weekday:'short',day:'numeric'})}</b>${miniWeather(d.weather_code[i])}<span>${weatherName(d.weather_code[i])}</span><strong>${valueText(d.temperature_2m_min[i],'°')} <em>${valueText(d.temperature_2m_max[i],'°')}</em></strong><small>${valueText(d.precipitation_probability_max[i],'% pioggia')}</small></article>`).join('')}</div><p class="forecast-footnote">L’incertezza aumenta andando avanti nei giorni. Le tendenze sono una lettura dei dati, non un bollettino di allerta.</p><div class="weather-tools-row">${contextButton('Qual è la tendenza dei prossimi sette giorni? Spiega anche l’incertezza.')}<button id="download-trend">Scarica la card meteo</button></div></section>`}
 if(weatherTab==='uscire'){const best=bestWindow(weather,activity);return `<section class="forecast-section"><div class="activity-choices">${[['walk','Passeggiata'],['cycle','Bici'],['outside','Tempo all’aperto']].map(([id,label])=>`<button data-activity="${id}" aria-pressed="${activity===id}">${label}</button>`).join('')}</div><div class="outing-window"><span>QUANDO CONVIENE USCIRE?</span><h2>${best?best.start.slice(11,16)+' – '+best.end.slice(11,16):'Nessuna finestra nei criteri'}</h2><p>${best?new Date(best.start.slice(0,10)+'T12:00:00').toLocaleDateString('it-IT',{weekday:'long',day:'numeric',month:'long'})+' · '+valueText(best.temp,'°')+' · pioggia fino al '+best.rain+'% · vento fino a '+best.wind+' km/h':'Nelle prossime 24 ore non ci sono dati sufficienti o condizioni entro i limiti scelti.'}</p><p class="small">Confrontiamo soltanto ore diurne e con dati completi. È un suggerimento organizzativo, non una garanzia di sicurezza.</p></div><details class="outing-criteria"><summary>Perché questo orario?</summary><p>${activity==='cycle'?'Per la bici: vento fino a 20 km/h, pioggia fino al 25%, temperatura da 8° a 29°.':activity==='outside'?'Per stare all’aperto: vento fino a 25 km/h, pioggia fino al 30%, temperatura da 12° a 30°.':'Per una passeggiata: vento fino a 25 km/h, pioggia fino al 30%, temperatura da 5° a 32°.'} Escludiamo le ore con temporali previsti; tra quelle rimanenti preferiamo meno pioggia, meno vento e temperature vicine a 21°. Controlla comunque le allerte ufficiali.</p></details><div class="weather-tools-row"><button data-atlas-question>Chiedi conferma alla zona</button>${contextButton('Aiutami a scegliere quando uscire nelle prossime 24 ore: '+({walk:'passeggiata',cycle:'bici',outside:'tempo all’aperto'}[activity])+'. Non dichiarare un luogo sicuro.')}</div></section>`}
 return `<section class="forecast-section"><div class="weather-metrics"><article><span>Vento</span><b>${valueText(w.wind_speed_10m,' km/h')}</b><small>Raffiche ${valueText(w.wind_gusts_10m,' km/h')}</small></article><article><span>Pioggia</span><b>${valueText(w.precipitation,' mm',1)}</b><small>Quantità stimata nell’intervallo</small></article><article><span>Umidità</span><b>${valueText(w.relative_humidity_2m,'%')}</b><small>Umidità relativa</small></article><article><span>Indice UV</span><b>${valueText(d?.uv_index_max?.[0],'',1)}</b><small>Massimo previsto oggi</small></article></div><div class="sun-times"><span>Alba <b>${d?.sunrise?.[0]?.slice(11,16)||'—'}</b></span><span>Tramonto <b>${d?.sunset?.[0]?.slice(11,16)||'—'}</b></span><span>Nuvole <b>${valueText(w.cloud_cover,'%')}</b></span></div><h2>Porto l’ombrello?</h2>${hourCards()}<div class="weather-tools-row"><button data-weather-tab="uscire">Trova un buon momento per uscire</button><button data-weather-tab="settimana">Guarda la tendenza</button></div></section>`}
 function weatherPage(){const {weather,weatherError,place}=ctx.get();return `<section class="weather-workspace"><div class="atlas-title"><div><span class="signal-kicker">METEO / LA TUA ZONA</span><h1>Le previsioni, <em>con chiarezza.</em></h1><p>${esc(place.name)}</p></div><a href="#guida" class="guide-link">? Guida</a></div>${weather?weatherHero():`<section class="weather-empty"><h2>${weatherError?'La fonte meteo non risponde':'Caricamento delle previsioni…'}</h2><p>${weatherError?'Riprova oppure cambia città.':'Puoi aprire la community mentre attendi.'}</p><button data-refresh-weather>Riprova</button><a href="#mappa">Cambia città</a></section>`}<div data-atmo-alert>${ctx.safetyHTML?.()||''}</div><div class="atlas-lente-slot">${ctx.lenteEntry?.({section:'weather',label:'La giornata, spiegata bene',description:'Ombrello, orari e tendenze. Chiedi a Lente.'})||''}</div><div class="forecast-tabs" aria-label="Periodo delle previsioni">${[['oggi','Adesso'],['ore','24 ore'],['settimana','7 giorni'],['uscire','Quando uscire']].map(([id,label])=>`<button data-weather-tab="${id}" aria-pressed="${weatherTab===id}">${label}</button>`).join('')}</div><div id="weather-content">${weatherContent()}</div><div class="weather-source">Fonte: <a href="https://open-meteo.com/" target="_blank" rel="noopener">Open-Meteo</a> · ${weather?esc(weather.timezone)+' · dato '+esc(weather.current.time.replace('T',' ')):'Dati non disponibili'} · previsioni da modello.</div><details class="weather-compare"><summary>Confronta con un’altra città</summary><label>Seconda città<select id="compare-city">${CITIES.filter(c=>c.name!==place.name).map(c=>`<option value="${c.id}" ${compare===c.id?'selected':''}>${c.name}</option>`).join('')}</select></label><div id="compare-result">${compareContent()}</div></details><div class="weather-links"><a href="#fitcheck">Come si veste la community? Apri Fit Check →</a><a href="#ripari">Quanto è vicina la pioggia? Trova copertura →</a><a href="#sfide">La sfida della tua città →</a><a href="#mappa-eventi">Apri mappa e radar</a><button data-atlas-community>La community qui</button><a href="https://www.protezionecivile.gov.it/it/" target="_blank" rel="noopener">Bollettini ufficiali ↗</a></div></section>`}
 function compareContent(){const c=cities.find(c=>c.id===compare),w=c?.current;return w?`<p><b>${esc(c.name)} ${valueText(w.temperature_2m,'°')}</b> · ${weatherName(w.weather_code)} · vento ${valueText(w.wind_speed_10m,' km/h')}</p><small>Open-Meteo · ${esc(w.time.replace('T',' '))} UTC</small><button data-compare-open>Apri questa città</button>`:`<p>${cityError||'Caricamento dei dati della città…'}</p>`}
 function guide(){return `<section class="app-guide">${professionGuide()}<details class="creator-guide"><summary>Nuovo: Oggi, timeline, personalità e Meteo Clash</summary><p>Oggi mostra subito temperatura, prossime ore e bollettino ufficiale della località. Segui le città per ritrovarle nel tuo account. Sul globo tocca una città e premi “Entra nel cielo della città” per aprire le Stories locali.</p><p>La timeline cambia simboli, valori e illuminazione del pianeta da −24 a +24 ore. Sono serie orarie del modello, anche nel passato: non un filmato radar o una previsione del movimento delle nuvole. Radar, Grandine e Segnalazioni conservano i propri orari.</p><p>Meteo Clash confronta due città e crea una card verticale con fonti e orari. Nello Studio trovi Clip, Testo, Meteo, Stile e Firma. “Testimonianza adesso” apre una sessione di tre minuti per scattare e pubblicare una foto dalla fotocamera: la galleria non compare, ma questo non certifica l’autenticità della scena.</p><p>Lente offre le voci Essenziale, Arcade, Premuroso e Cinico. I bollettini ufficiali italiani e le condizioni che richiedono prudenza sospendono l’ironia; con allerta rossa la risposta è deterministica e rimanda alle indicazioni ufficiali. Fuori copertura o con fonte assente, lo stato rimane non verificato.</p><a href="#home">Apri Oggi →</a><a href="#clash">Prova Meteo Clash →</a></details><details class="creator-guide"><summary>Nuovo: redazione, Studio e Storm Rooms</summary><p>Dal pulsante Crea della community apri lo Studio: importa una foto o un video, scegli il layout e prepara una slide quadrata o una clip verticale. La fotocamera richiede consenso e si ferma quando lasci la pagina. Prima di pubblicare, controlla l’anteprima e i diritti sui contenuti.</p><p>La Redazione contiene i bollettini Patch Notes, la finestra Sky-Drop e i tuoi asset. L’aspetto automatico cambia con il meteo; nel feed pioggia trovi post dichiarati Pioggia delle ultime due ore. “Tutti i cieli” torna al feed completo. Le Storm Rooms chiedono una posizione singola e hanno accesso e durata limitati.</p><a href="#studio">Apri Studio →</a><a href="#redazione">La tua redazione →</a></details><div class="atlas-title"><div><h1>Ti orienti in un minuto.</h1><p>Una città, tre punti di vista: previsione, radar e persone.</p></div><a href="#mondo">Torna alla mappa</a></div><div class="guide-steps"><article><span>1</span><div><h2>Scegli dove guardare</h2><p>Cerca una città dal selettore in alto o usa la posizione. Se compaiono nomi uguali, scegli anche regione e paese. “Vicino a me” usa la posizione soltanto dopo il tuo consenso.</p><a href="#mondo">Apri la mappa →</a></div></article><article><span>2</span><div><h2>Scegli cosa vedere</h2><p><b>Meteo:</b> condizioni previste. <b>Pioggia:</b> quantità in millimetri. <b>Radar:</b> immagini recenti delle precipitazioni, con orario. <b>Grandine:</b> post delle ultime due ore. <b>Segnalazioni:</b> contributi delle ultime 24 ore.</p><p>In Pioggia e Grandine trovi le distanze disponibili e i luoghi coperti entro 5 km. Premi “Usa la mia posizione” per usare il GPS. Il radar non identifica da solo la grandine e non calcola quando arriverà.</p><a href="#mappa">Esplora i livelli →</a></div></article><article><span>3</span><div><h2>Passa dai numeri alle persone</h2><p>Apri “Quando uscire?” per confrontare gli orari. Premi “Com’è davvero lì?” per preparare una domanda alla community. Controlla sempre località, autore e data dei post. In Community puoi filtrare gli argomenti, seguire persone, nascondere post e partecipare alle sfide delle città.</p><a href="#tendenze">Apri il meteo →</a></div></article><article><span>4</span><div><h2>Chiedi una spiegazione</h2><p>Lente IA si apre accanto alla mappa, alle previsioni o al post. I suggerimenti preparano una domanda: premi Invia quando vuoi. In Community legge solo i testi pubblici del campione, non le immagini. Le fonti sono sotto la risposta. ${ctx.get().aiReady?'Il servizio IA è collegato.':'Il servizio IA non è ancora collegato; le spiegazioni dei livelli e la lettura dei dati sono già disponibili.'} Le risposte IA possono contenere errori.</p><a href="#assistente">Apri l’assistente →</a></div></article></div><details class="creator-guide"><summary>Fit Check: i consigli sulla mappa</summary><p>Apri Fit Check dalla Community, dalla mappa o dal Meteo. Trovi foto e video pubblicati nelle ultime 24 ore, entro 5 o 20 km dal centro scelto. I pin raggruppano zone approssimate e non indicano un indirizzo o un tragitto sicuro.</p><p>Per contribuire, pubblica una foto o un video, poi premi “Aggiungi alla mappa Fit Check”. Scegli un consiglio e tocca la mappa per indicare la zona. Puoi usare il GPS solo premendo “Usa la mia zona”. Controlla l’area e conferma la pubblicazione. “Rimuovi dalla mappa” cancella la zona, lasciando il post originale.</p><a href="#fitcheck">Esplora Fit Check →</a></details><section class="guide-facts"><h2>Due cose da ricordare</h2><p>Il 40% di pioggia indica una probabilità, non una quantità. Una segnalazione di una persona non è una previsione o un’allerta ufficiale.</p><p>La mappa locale usa MapLibre e OpenFreeMap / OpenStreetMap. Il radar viene da RainViewer; vento e temperatura da Open-Meteo. Le foto e le segnalazioni delle persone sono distinte dai dati del modello.</p><a href="#impostazioni">Testo, movimento e comfort</a> · <a href="#informazioni">Fonti e dettagli</a></section></section>`}
 async function loadCities(force=false){if(cityLoading||(!force&&Date.now()-cityLoaded<600000))return;cityLoading=true;try{const d=await ctx.api('atlas/cities');cities=d.cities;cityLoaded=Date.now();cityError=''}catch(e){cityError=e.message}finally{cityLoading=false;refresh();if($('#compare-result'))$('#compare-result').innerHTML=compareContent();bindCompare()}}
 function bindCompare(){const el=$('#compare-city');if(el)el.onchange=()=>{compare=el.value;$('#compare-result').innerHTML=compareContent();bindCompare()};const b=$('[data-compare-open]');if(b)b.onclick=()=>{const c=cities.find(c=>c.id===compare);if(c)ctx.choose(c)}}
 function bindActions(){document.querySelectorAll('[data-atlas-ai]').forEach(b=>b.onclick=()=>ctx.askAI(b.dataset.atlasAi));document.querySelectorAll('[data-atlas-community]').forEach(b=>b.onclick=()=>ctx.community());document.querySelectorAll('[data-atlas-question]').forEach(b=>b.onclick=()=>ctx.askCommunity());document.querySelectorAll('[data-weather-tab]').forEach(b=>b.onclick=()=>{weatherTab=b.dataset.weatherTab;ctx.render()});document.querySelectorAll('[data-activity]').forEach(b=>b.onclick=()=>{activity=b.dataset.activity;ctx.render()});bindCompare()}
function refresh(){if(ctx.get().route!=='tendenze')return;const empty=$('.weather-empty');if(empty&&ctx.get().weather)empty.outerHTML=weatherHero();const hero=$('.weather-hero');if(hero)hero.outerHTML=weatherHero();if($('#weather-content'))$('#weather-content').innerHTML=weatherContent();bindActions()}
function bind(){if(ctx.get().route==='tendenze'){loadCities();bindActions()}}
return {weatherPage,guide,page:weatherPage,bind,refresh,dispose(){},invalidateReports(){},aiContext:()=>({section:'weather',layer:'meteo'})};
}
